#!/bin/bash
# ============================================================
# AgentDeck MCP Bridge — self-contained installer (v1.0.0)
# Installs a zero-dependency MCP server (Streamable HTTP) on this VPS:
#   /opt/agentdeck-bridge/mcp-gateway.js
#   systemd unit: agentdeck-bridge.service  (127.0.0.1:3117)
# Expose it via YOUR OWN cloudflared tunnel (outbound-only, no open ports).
# Every tool call is audit-logged to /opt/agentdeck-bridge/audit.log
# ============================================================
set -euo pipefail

AD_DIR="/opt/agentdeck-bridge"
AD_JS="$AD_DIR/mcp-gateway.js"
AD_ENV="$AD_DIR/bridge.env"
AD_UNIT="/etc/systemd/system/agentdeck-bridge.service"
AD_PORT="3117"

echo "==> AgentDeck MCP Bridge installer"

# --- node check ---
NODE_BIN="$(command -v node || true)"
if [ -z "$NODE_BIN" ]; then
  echo "ERROR: node not found. Install Node.js 18+ first (e.g. curl -fsSL https://deb.nodesource.com/setup_20.x | bash - && apt-get install -y nodejs)"
  exit 1
fi
NODE_MAJOR="$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)"
if [ "$NODE_MAJOR" -lt 18 ]; then
  echo "ERROR: Node >= 18 required (found $(node --version)). Upgrade node and re-run."
  exit 1
fi
echo "==> node: $(node --version) at $NODE_BIN"

# --- files ---
mkdir -p "$AD_DIR"
printf '%s' "" | base64 -d > "$AD_JS"
chmod 600 "$AD_JS"
echo "==> wrote $AD_JS"

# --- token (persist across reinstalls) ---
if [ -f "$AD_ENV" ] && grep -q "AGENTDECK_MCP_TOKEN=" "$AD_ENV"; then
  echo "==> keeping existing token in $AD_ENV"
else
  TOKEN="$(openssl rand -hex 24 2>/dev/null || head -c 24 /dev/urandom | od -An -tx1 | tr -d ' \n')"
  echo "AGENTDECK_MCP_TOKEN=$TOKEN" > "$AD_ENV"
  chmod 600 "$AD_ENV"
  echo "==> generated new token"
fi
. "$AD_ENV"

# --- systemd unit ---
cat > "$AD_UNIT" <<UNIT
[Unit]
Description=AgentDeck MCP Bridge (Streamable HTTP on 127.0.0.1:$AD_PORT)
After=network.target

[Service]
ExecStart=$NODE_BIN $AD_JS
EnvironmentFile=$AD_ENV
Environment=PORT=$AD_PORT
Restart=always
RestartSec=3
WorkingDirectory=$AD_DIR
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
UNIT

systemctl daemon-reload
systemctl enable agentdeck-bridge >/dev/null 2>&1 || true
systemctl restart agentdeck-bridge
sleep 1

if curl -fsS "http://127.0.0.1:$AD_PORT/health" >/dev/null 2>&1; then
  echo "==> bridge is UP on 127.0.0.1:$AD_PORT"
else
  echo "WARNING: health check failed — check: journalctl -u agentdeck-bridge -n 20"
fi

TOKEN_VALUE="$(grep AGENTDECK_MCP_TOKEN= "$AD_ENV" | cut -d= -f2)"

echo ""
echo "============================================================"
echo " INSTALL DONE"
echo "============================================================"
echo ""
echo "Your bridge token (send this together with the tunnel URL):"
echo ""
echo "    $TOKEN_VALUE"
echo ""
echo "------------------------------------------------------------"
echo " NEXT: expose via cloudflared (pick ONE path)"
echo "------------------------------------------------------------"
echo ""
echo " PATH 1 — config-file tunnel (/etc/cloudflared/config.yml):"
echo "   1) pick a hostname, e.g. adbridge.yourdomain.com"
echo "   2) cloudflared tunnel route dns <TUNNEL-NAME> adbridge.yourdomain.com"
echo "   3) add ingress rule BEFORE the catch-all in config.yml:"
echo "        - hostname: adbridge.yourdomain.com"
echo "          service: http://localhost:$AD_PORT"
echo "   4) systemctl restart cloudflared"
echo ""
echo " PATH 2 — dashboard-managed tunnel:"
echo "   Cloudflare Zero Trust dashboard -> Networks -> Tunnels ->"
echo "   your tunnel -> Public Hostname -> Add:"
echo "        subdomain: adbridge   domain: yourdomain.com"
echo "        service:   http://localhost:$AD_PORT"
echo ""
echo " THEN verify from outside:"
echo "   curl https://adbridge.yourdomain.com/health"
echo ""
echo " Send me: the tunnel URL + the token above. That's it."
echo "============================================================"
